// End-to-end smoke test for the photo gallery. Launches a headless
// Chromium against the locally running `npm run preview` server and
// exercises the gallery functions through `window.gallery`.

import puppeteer from 'puppeteer-core';
import { writeFileSync, readFileSync } from 'node:fs';
import { Buffer } from 'node:buffer';

// 1x1 red JPEG, base64 encoded.
const RED_JPEG_B64 =
  '';

const RED_JPEG_BYTES = Buffer.from(RED_JPEG_B64, 'base64');

function log(...args) {
  console.log('[test]', ...args);
}

async function main() {
  // Start Chromium
  const browser = await puppeteer.launch({
    executablePath:
      '/root/.cache/ms-playwright/chromium-1228/chrome-linux64/chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  });
  const page = await browser.newPage();
  page.on('console', (msg) => log('console:', msg.type(), msg.text()));
  page.on('pageerror', (err) => log('pageerror:', err.message));

  log('navigating');
  await page.goto('http://localhost:4173/', { waitUntil: 'networkidle0' });

  // Sanity-check the DOM
  const initialStatus = await page.$eval('#capture-status', (el) => el.textContent);
  log('initial status:', JSON.stringify(initialStatus));
  if (initialStatus !== 'idle') {
    throw new Error(`initial status should be 'idle', got '${initialStatus}'`);
  }
  const hasBtn = await page.$('#capture-btn');
  if (!hasBtn) throw new Error('capture-btn missing');
  log('ids present in DOM');

  // Sanity-check window.gallery
  const galleryCheck = await page.evaluate(() => ({
    capturePhoto: typeof window.gallery?.capturePhoto,
    listPhotos: typeof window.gallery?.listPhotos,
    deletePhoto: typeof window.gallery?.deletePhoto,
  }));
  log('window.gallery:', galleryCheck);
  if (
    galleryCheck.capturePhoto !== 'function' ||
    galleryCheck.listPhotos !== 'function' ||
    galleryCheck.deletePhoto !== 'function'
  ) {
    throw new Error('window.gallery.* not all functions');
  }

  // Now exercise capturePhoto by stubbing out Camera.takePhoto to
  // simulate a Web fallback where the file picker handed us a file.
  log('programmatically exercising capturePhoto (simulating a Web file picker)');

  const captureResult = await page.evaluate(async (redJpegB64) => {
    // Simulate the Capacitor Camera web fallback result by calling
    // capturePhoto and providing the picked file via a stubbed Camera.takePhoto.
    const cameraModule = await import('/node_modules/@capacitor/camera/dist/esm/index.js');
    const originalTakePhoto = cameraModule.Camera.takePhoto.bind(cameraModule.Camera);
    cameraModule.Camera.takePhoto = async () => ({
      type: 'photo',
      base64String: redJpegB64,
      format: 'jpeg',
      saved: false,
    });
    try {
      const path = await window.gallery.capturePhoto();
      return { path };
    } finally {
      cameraModule.Camera.takePhoto = originalTakePhoto;
    }
  }, RED_JPEG_B64);

  log('capturePhoto returned:', captureResult);
  if (!captureResult.path || !/^photos\/\d{4}-\d{2}-\d{2}T.*\.jpeg$/.test(captureResult.path)) {
    throw new Error(`unexpected path: ${captureResult.path}`);
  }

  const listed1 = await page.evaluate(async () => window.gallery.listPhotos());
  log('listPhotos after capture:', listed1);
  if (!Array.isArray(listed1) || listed1.length !== 1 || listed1[0] !== captureResult.path) {
    throw new Error(`expected [${captureResult.path}], got ${JSON.stringify(listed1)}`);
  }

  // Verify the persisted file (IndexedDB on Web)
  const dbInfo = await page.evaluate(async (path) => {
    return new Promise((resolve) => {
      const req = indexedDB.open('CapacitorFilesystem');
      req.onsuccess = () => {
        const db = req.result;
        const tx = db.transaction(['entries'], 'readonly');
        const store = tx.objectStore('entries');
        const storeNames = Array.from(db.objectStoreNames);
        const getReq = store.get(path);
        getReq.onsuccess = () => resolve({ storeNames, hit: getReq.result });
        getReq.onerror = () => resolve({ storeNames, error: 'get failed' });
      };
      req.onerror = () => resolve({ error: 'open failed' });
    });
  }, captureResult.path);
  log('IndexedDB lookup:', dbInfo);
  if (!dbInfo.hit || dbInfo.hit.type !== 'file') {
    throw new Error('persisted file not found in IndexedDB');
  }

  // Verify the Preferences index (localStorage on Web under
  // CapacitorStorage.photo_index).
  const stored = await page.evaluate(() =>
    window.localStorage.getItem('CapacitorStorage.photo_index')
  );
  log('localStorage index:', stored);
  if (JSON.stringify(JSON.parse(stored)) !== JSON.stringify([captureResult.path])) {
    throw new Error('Preferences/localStorage index mismatch');
  }

  // Capture a second photo and verify insertion order is preserved.
  const capture2 = await page.evaluate(async (redJpegB64) => {
    const cameraModule = await import('/node_modules/@capacitor/camera/dist/esm/index.js');
    const originalTakePhoto = cameraModule.Camera.takePhoto.bind(cameraModule.Camera);
    cameraModule.Camera.takePhoto = async () => ({
      type: 'photo',
      base64String: redJpegB64,
      format: 'jpeg',
      saved: false,
    });
    try {
      return await window.gallery.capturePhoto();
    } finally {
      cameraModule.Camera.takePhoto = originalTakePhoto;
    }
  }, RED_JPEG_B64);
  log('capturePhoto returned:', capture2);

  const listed2 = await page.evaluate(async () => window.gallery.listPhotos());
  log('listPhotos after second capture:', listed2);
  if (listed2.length !== 2 || listed2[0] !== captureResult.path || listed2[1] !== capture2) {
    throw new Error('insertion order should be preserved');
  }

  // Delete the first photo.
  await page.evaluate(async (p) => window.gallery.deletePhoto(p), captureResult.path);
  const listed3 = await page.evaluate(async () => window.gallery.listPhotos());
  log('listPhotos after delete:', listed3);
  if (listed3.length !== 1 || listed3[0] !== capture2) {
    throw new Error('delete should remove only the matching path');
  }

  // Delete a non-existent path - index should still update (and stay the same).
  await page.evaluate(async (p) => window.gallery.deletePhoto(p), 'photos/does-not-exist.jpeg');
  const listed4 = await page.evaluate(async () => window.gallery.listPhotos());
  log('listPhotos after noop delete:', listed4);
  if (listed4.length !== 1 || listed4[0] !== capture2) {
    throw new Error('noop delete should not throw and should not corrupt the index');
  }

  // Click the button: capture-status should reach `saved: <path>`
  const beforeClickStatus = await page.$eval('#capture-status', (el) => el.textContent);
  log('status before click:', beforeClickStatus);

  await page.evaluate(async (redJpegB64) => {
    const cameraModule = await import('/node_modules/@capacitor/camera/dist/esm/index.js');
    cameraModule.Camera.takePhoto = async () => ({
      type: 'photo',
      base64String: redJpegB64,
      format: 'jpeg',
      saved: false,
    });
  }, RED_JPEG_B64);
  await page.click('#capture-btn');
  // Give it some time
  for (let i = 0; i < 20; i++) {
    const txt = await page.$eval('#capture-status', (el) => el.textContent);
    if (txt.startsWith('saved:')) {
      log('status after click:', txt);
      break;
    }
    if (txt.startsWith('error:')) {
      throw new Error('capture status shows error: ' + txt);
    }
    await new Promise((r) => setTimeout(r, 50));
  }
  const afterClickStatus = await page.$eval('#capture-status', (el) => el.textContent);
  log('final status:', afterClickStatus);
  if (!afterClickStatus.startsWith('saved:')) {
    throw new Error('button click did not reach saved state');
  }

  await browser.close();
  log('all checks passed');
}

main().catch((err) => {
  console.error('[test] FAILED:', err.stack || err.message);
  process.exit(1);
});

