// End-to-end smoke test for the photo gallery. Launches a headless
// Chromium against the locally running `npm run preview` server and
// exercises the gallery functions through `window.gallery`.

import puppeteer from 'puppeteer-core';

// 1x1 red JPEG, base64 encoded.
const RED_JPEG_B64 =
  '';

const log = (...args) => console.log('[test]', ...args);

/**
 * Drive a single capture round-trip through the actual Capacitor
 * Camera web fallback by attaching a synthetic File to the camera
 * plugin's hidden <input type="file">.
 */
async function driveCapture(page, buttonId = '#capture-btn') {
  const result = await page.evaluate(
    async ({ redJpegB64, buttonId }) => {
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      // Wait until the file input exists (or gets created by the
      // Camera web fallback on click).
      const beforeClick = !!document.querySelector('#_capacitor-camera-input-takephoto');
      // Hook the <input type="file"> creation so we can set a File
      // before the camera fallback calls click() on it.
      const observer = new MutationObserver((records) => {
        for (const r of records) {
          for (const node of r.addedNodes) {
            if (node instanceof HTMLElement && node.id === '_capacitor-camera-input-takephoto') {
              const dt = new DataTransfer();
              const bytes = Uint8Array.from(atob(redJpegB64), (c) => c.charCodeAt(0));
              const file = new File([bytes], 'photo.jpeg', { type: 'image/jpeg' });
              dt.items.add(file);
              node.files = dt.files;
              node.dispatchEvent(new Event('change', { bubbles: true }));
            }
            if (node instanceof HTMLInputElement && node.id === '_capacitor-camera-input-takephoto') {
              const dt = new DataTransfer();
              const bytes = Uint8Array.from(atob(redJpegB64), (c) => c.charCodeAt(0));
              const file = new File([bytes], 'photo.jpeg', { type: 'image/jpeg' });
              dt.items.add(file);
              node.files = dt.files;
              node.dispatchEvent(new Event('change', { bubbles: true }));
            }
          }
        }
      });
      observer.observe(document.body, { childList: true, subtree: true });

      const btn = document.querySelector(buttonId);
      if (!btn) throw new Error('capture button not found');
      btn.click();

      // Wait for status to either become "saved: ..." or "error: ...".
      const start = Date.now();
      while (Date.now() - start < 5000) {
        const s = document.getElementById('capture-status');
        if (!s) continue;
        const txt = s.textContent || '';
        if (txt.startsWith('saved:') || txt.startsWith('error:')) {
          observer.disconnect();
          return { status: txt, hadFileInputBefore: beforeClick };
        }
        await sleep(20);
      }
      observer.disconnect();
      throw new Error('timed out waiting for capture-status to update');
    },
    { redJpegB64: RED_JPEG_B64, buttonId }
  );

  return result;
}

async function main() {
  // Start Chromium
  const browser = await puppeteer.launch({
    executablePath:
      '/root/.cache/ms-playwright/chromium-1228/chrome-linux64/chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  });
  const page = await browser.newPage();
  page.on('console', (msg) => log('console:', msg.type(), msg.text()));
  page.on('pageerror', (err) => log('pageerror:', err.message));

  log('navigating');
  await page.goto('http://localhost:4173/', { waitUntil: 'networkidle0' });

  // Sanity-check the DOM
  const initialStatus = await page.$eval('#capture-status', (el) => el.textContent);
  log('initial status:', JSON.stringify(initialStatus));
  if (initialStatus !== 'idle') {
    throw new Error(`initial status should be 'idle', got '${initialStatus}'`);
  }
  if (!(await page.$('#capture-btn'))) throw new Error('capture-btn missing');
  log('ids present in DOM');

  // Sanity-check window.gallery
  const galleryCheck = await page.evaluate(() => ({
    capturePhoto: typeof window.gallery?.capturePhoto,
    listPhotos: typeof window.gallery?.listPhotos,
    deletePhoto: typeof window.gallery?.deletePhoto,
  }));
  log('window.gallery:', galleryCheck);
  if (
    galleryCheck.capturePhoto !== 'function' ||
    galleryCheck.listPhotos !== 'function' ||
    galleryCheck.deletePhoto !== 'function'
  ) {
    throw new Error('window.gallery.* not all functions');
  }

  // 1. Button-driven capture
  const r1 = await driveCapture(page, '#capture-btn');
  log('capture #1 status:', r1.status);
  if (!r1.status.startsWith('saved:')) {
    throw new Error(`expected 'saved: ...', got '${r1.status}'`);
  }
  const path1 = r1.status.substring('saved: '.length);
  log('path1:', path1);
  if (!/^photos\/\d{4}-\d{2}-\d{2}T.*\.jpeg$/.test(path1)) {
    throw new Error(`unexpected path1: ${path1}`);
  }

  // 2. Verify listPhotos returns the freshly-written path
  const list1 = await page.evaluate(async () => window.gallery.listPhotos());
  log('listPhotos after capture #1:', list1);
  if (list1.length !== 1 || list1[0] !== path1) {
    throw new Error(`expected [${path1}], got ${JSON.stringify(list1)}`);
  }

  // 3. Verify the persisted file (IndexedDB on Web, db "Disc")
  const dbInfo = await page.evaluate(async (path) => {
    return new Promise((resolve) => {
      const req = indexedDB.open('Disc');
      req.onsuccess = () => {
        const db = req.result;
        const tx = db.transaction(['FileStorage'], 'readonly');
        const store = tx.objectStore('FileStorage');
        const getReq = store.get(path);
        getReq.onsuccess = () => resolve({ hit: getReq.result });
        getReq.onerror = () => resolve({ error: 'get failed' });
      };
      req.onerror = () => resolve({ error: 'open failed' });
    });
  }, path1);
  log('IndexedDB lookup for path1:', dbInfo);
  if (!dbInfo.hit || dbInfo.hit.type !== 'file') {
    throw new Error('persisted file not found in IndexedDB');
  }

  // 4. Verify the Preferences index (localStorage on Web under
  //    "CapacitorStorage.photo_index")
  const stored = await page.evaluate(() =>
    window.localStorage.getItem('CapacitorStorage.photo_index')
  );
  log('localStorage index:', stored);
  if (JSON.stringify(JSON.parse(stored)) !== JSON.stringify([path1])) {
    throw new Error('Preferences/localStorage index mismatch');
  }

  // 5. Insert a second photo and verify insertion order is preserved.
  await page.evaluate(() => {
    // Wipe status so we can detect the next click cycle.
    document.getElementById('capture-status').textContent = 'idle';
  });
  const r2 = await driveCapture(page, '#capture-btn');
  log('capture #2 status:', r2.status);
  if (!r2.status.startsWith('saved:')) {
    throw new Error(`expected 'saved: ...', got '${r2.status}'`);
  }
  const path2 = r2.status.substring('saved: '.length);
  log('path2:', path2);
  const list2 = await page.evaluate(async () => window.gallery.listPhotos());
  log('listPhotos after capture #2:', list2);
  if (list2.length !== 2 || list2[0] !== path1 || list2[1] !== path2) {
    throw new Error(`insertion order should be [${path1}, ${path2}], got ${JSON.stringify(list2)}`);
  }

  // 6. Delete the first photo via window.gallery
  await page.evaluate(async (p) => window.gallery.deletePhoto(p), path1);
  const list3 = await page.evaluate(async () => window.gallery.listPhotos());
  log('listPhotos after delete path1:', list3);
  if (list3.length !== 1 || list3[0] !== path2) {
    throw new Error('delete should remove only the matching path');
  }

  // 7. Delete a non-existent path - it must not throw and must not change the index
  await page.evaluate(async () => {
    try {
      await window.gallery.deletePhoto('photos/does-not-exist.jpeg');
      window.__deleteError = null;
    } catch (e) {
      window.__deleteError = String(e);
    }
  });
  const list4 = await page.evaluate(async () => window.gallery.listPhotos());
  const err4 = await page.evaluate(() => window.__deleteError);
  log('listPhotos after noop delete:', list4, 'err:', err4);
  if (err4 !== null) throw new Error('deletePhoto with missing file must not throw');
  if (list4.length !== 1 || list4[0] !== path2) {
    throw new Error('noop delete should not corrupt the index');
  }

  // 8. Verify the deleted file is gone from IndexedDB
  const dbAfterDelete = await page.evaluate(async (path) => {
    return new Promise((resolve) => {
      const req = indexedDB.open('Disc');
      req.onsuccess = () => {
        const db = req.result;
        const tx = db.transaction(['FileStorage'], 'readonly');
        const store = tx.objectStore('FileStorage');
        const getReq = store.get(path);
        getReq.onsuccess = () => resolve({ hit: getReq.result });
        getReq.onerror = () => resolve({ error: 'get failed' });
      };
      req.onerror = () => resolve({ error: 'open failed' });
    });
  }, path1);
  log('IndexedDB lookup after delete:', dbAfterDelete);
  if (dbAfterDelete.hit !== undefined) {
    throw new Error('deleted file should be gone from IndexedDB');
  }

  await browser.close();
  log('all checks passed');
}

main().catch((err) => {
  console.error('[test] FAILED:', err.stack || err.message);
  process.exit(1);
});

